// Two unevenly spaced combustion pulses per cycle, with low exhaust resonance.
export function makeV2Loop(sampleRate=48000){const cycle=.16,cycles=16,samples=new Float32Array(Math.round(sampleRate*cycle*cycles));let seed=71;const events=[];for(let i=0;i<cycles;i++){events.push(i*cycle,i*cycle+cycle*.6);}for(const start of events){for(let n=0;n<sampleRate*.12;n++){const index=(Math.round(start*sampleRate)+n)%samples.length;const t=n/sampleRate;seed=(seed*1664525+1013904223)>>>0;const noise=(seed/4294967296-.5)*2;const attack=Math.min(1,t/.0015),decay=Math.exp(-t*38);const thump=Math.sin(2*Math.PI*(51*t-65*t*t))+.34*Math.sin(2*Math.PI*103*t)+noise*.16*Math.exp(-t*50);samples[index]+=Math.tanh(thump*1.55)*decay*attack*.66;}}return samples;}
export function createV2Audio(sound){const ctx=new(window.AudioContext||window.webkitAudioContext)(),master=ctx.createGain(),gain=ctx.createGain(),filter=ctx.createBiquadFilter(),resonance=ctx.createBiquadFilter();master.gain.value=sound?.58:0;master.connect(ctx.destination);gain.gain.value=0;gain.connect(master);filter.type='lowpass';filter.frequency.value=780;filter.Q.value=.65;resonance.type='peaking';resonance.frequency.value=112;resonance.Q.value=.8;resonance.gain.value=4;const source=ctx.createBufferSource(),samples=makeV2Loop(ctx.sampleRate),buffer=ctx.createBuffer(1,samples.length,ctx.sampleRate);buffer.copyToChannel(samples,0);source.buffer=buffer;source.loop=true;const dc=ctx.createBiquadFilter();dc.type='highpass';dc.frequency.value=26;source.connect(dc);dc.connect(filter);filter.connect(resonance);resonance.connect(gain);source.start();return {ctx,master,gain,filter,source};}
export function updateV2Audio(audio,{sound,driving,speed,throttle,boost}){const t=audio.ctx.currentTime;audio.master.gain.setTargetAtTime(sound?.58:0,t,.06);audio.gain.gain.setTargetAtTime(driving?(throttle?.32:.2)*(audio.voiceUntil>t?.28:1):0,t,.06);const rate=.78+Math.max(0,speed)*.059+(throttle?.22:0)+(boost?.25:0);audio.source.playbackRate.setTargetAtTime(rate,t,.09);audio.filter.frequency.setTargetAtTime(700+speed*24+(throttle?250:0),t,.1);}
